1	import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
2	import { BrowserRouter, Route, Routes, Navigate } from "react-router-dom";
3	import { Toaster as Sonner } from "@/components/ui/sonner";
4	import { Toaster } from "@/components/ui/toaster";
5	import { TooltipProvider } from "@/components/ui/tooltip";
6	import { AppLayout } from "@/components/AppLayout";
7	import Dashboard from "@/pages/Dashboard";
8	import Scan from "@/pages/Scan";
9	import Reports from "@/pages/Reports";
10	import AuditReport from "@/pages/AuditReport";
11	import Integrations from "@/pages/Integrations";
12	import SettingsPage from "@/pages/Settings";
13	import Pricing from "@/pages/Pricing";
14	import Landing from "@/pages/Landing";
15	import Login from "@/pages/Login";
16	import Signup from "@/pages/Signup";
17	import NotFound from "@/pages/NotFound";
18	
19	const queryClient = new QueryClient();
20	
21	const App = () => (
22	  <QueryClientProvider client={queryClient}>
23	    <TooltipProvider>
24	      <Toaster />
25	      <Sonner />
26	      <BrowserRouter>
27	        <Routes>
28	          {/* Public routes */}
29	          <Route path="/" element={<Landing />} />
30	          <Route path="/login" element={<Login />} />
31	          <Route path="/signup" element={<Signup />} />
32	
33	          {/* App routes */}
34	          <Route element={<AppLayout />}>
35	            <Route path="/dashboard" element={<Dashboard />} />
36	            <Route path="/scan" element={<Scan />} />
37	            <Route path="/reports" element={<Reports />} />
38	            <Route path="/reports/:id" element={<AuditReport />} />
39	            <Route path="/integrations" element={<Integrations />} />
40	            <Route path="/settings" element={<SettingsPage />} />
41	            <Route path="/pricing" element={<Pricing />} />
42	          </Route>
43	          <Route path="*" element={<NotFound />} />
44	        </Routes>
45	      </BrowserRouter>
46	    </TooltipProvider>
47	  </QueryClientProvider>
48	);
49	
50	export default App;
51

1	import { useState } from "react";
2	import { useParams, Link } from "react-router-dom";
3	import {
4	  Download,
5	  Share2,
6	  RefreshCw,
7	  ArrowLeft,
8	  Globe,
9	  Calendar,
10	  AlertCircle,
11	  Zap,
12	  TrendingUp,
13	  Copy,
14	  Check,
15	  BarChart2,
16	  Lock,
17	} from "lucide-react";
18	import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
19	import { Button } from "@/components/ui/button";
20	import { Badge } from "@/components/ui/badge";
21	import { Separator } from "@/components/ui/separator";
22	import {
23	  Tabs,
24	  TabsContent,
25	  TabsList,
26	  TabsTrigger,
27	} from "@/components/ui/tabs";
28	import {
29	  Tooltip,
30	  TooltipContent,
31	  TooltipProvider,
32	  TooltipTrigger,
33	} from "@/components/ui/tooltip";
34	import { ScoreRing } from "@/components/shared/ScoreRing";
35	import { PillarProgressBar } from "@/components/shared/PillarProgressBar";
36	import { FindingCard } from "@/components/shared/FindingCard";
37	import { BrowserFrame } from "@/components/shared/BrowserFrame";
38	import { PageTransition } from "@/components/shared/PageTransition";
39	import { SeverityBadge } from "@/components/shared/SeverityBadge";
40	import {
41	  getScoreColor,
42	  getScoreBgLight,
43	  getScoreLabel,
44	  getPercentileRank,
45	  getIndustryBenchmark,
46	  formatScore,
47	  getEffortLabel,
48	  getEffortColor,
49	  getScoreBgColor,
50	} from "@/lib/score-utils";
51	import { CRO_PILLARS } from "@/lib/constants";
52	import { MOCK_SCANS, MOCK_PILLAR_RESULTS, MOCK_USER } from "@/lib/mock-data";
53	import { cn } from "@/lib/utils";
54	import type { Finding, Severity } from "@/types";
55	
56	// ── Helpers ─────────────────────────────────────────────────────
57	
58	function formatDateTime(dateStr: string) {
59	  return new Date(dateStr).toLocaleDateString("en-US", {
60	    month: "long",
61	    day: "numeric",
62	    year: "numeric",
63	    hour: "numeric",
64	    minute: "2-digit",
65	  });
66	}
67	
68	function deviceLabel(device: string) {
69	  if (device === "both") return "Desktop & Mobile";
70	  return device === "desktop" ? "Desktop" : "Mobile";
71	}
72	
73	/** Annotation dots positioned over the browser mockup to simulate real audit marks */
74	const ANNOTATION_DOTS: {
75	  id: string;
76	  label: string;
77	  severity: Severity;
78	  top: string;
79	  left: string;
80	  findingRef: string;
81	}[] = [
82	  { id: "a1", label: "CTA below fold", severity: "critical", top: "62%", left: "50%", findingRef: "f_ct01" },
83	  { id: "a2", label: "Low contrast button", severity: "critical", top: "64%", left: "54%", findingRef: "f_ct02" },
84	  { id: "a3", label: "No social proof", severity: "critical", top: "18%", left: "75%", findingRef: "f_ts01" },
85	  { id: "a4", label: "Generic headline", severity: "warning", top: "12%", left: "35%", findingRef: "f_vp01" },
86	  { id: "a5", label: "Missing trust badges", severity: "critical", top: "85%", left: "48%", findingRef: "f_ts03" },
87	  { id: "a6", label: "Stock photos", severity: "critical", top: "72%", left: "22%", findingRef: "f_ts02" },
88	  { id: "a7", label: "Weak subheadline", severity: "warning", top: "20%", left: "38%", findingRef: "f_vp02" },
89	  { id: "a8", label: "Features compete with hero", severity: "warning", top: "44%", left: "50%", findingRef: "f_vh01" },
90	];
91	
92	const severityDotColor: Record<Severity, string> = {
93	  critical: "bg-red-500 border-red-300 shadow-red-500/40",
94	  warning: "bg-amber-500 border-amber-300 shadow-amber-500/40",
95	  info: "bg-blue-500 border-blue-300 shadow-blue-500/40",
96	  passed: "bg-green-500 border-green-300 shadow-green-500/40",
97	};
98	
99	// ── Copy Button ─────────────────────────────────────────────────
100	
101	function CopyButton({ text }: { text: string }) {
102	  const [copied, setCopied] = useState(false);
103	
104	  const handleCopy = async () => {
105	    try {
106	      await navigator.clipboard.writeText(text);
107	      setCopied(true);
108	      setTimeout(() => setCopied(false), 2000);
109	    } catch {
110	      // Fallback for older browsers
111	      const textarea = document.createElement("textarea");
112	      textarea.value = text;
113	      document.body.appendChild(textarea);
114	      textarea.select();
115	      document.execCommand("copy");
116	      document.body.removeChild(textarea);
117	      setCopied(true);
118	      setTimeout(() => setCopied(false), 2000);
119	    }
120	  };
121	
122	  return (
123	    <TooltipProvider delayDuration={200}>
124	      <Tooltip>
125	        <TooltipTrigger asChild>
126	          <button
127	            onClick={handleCopy}
128	            className={cn(
129	              "inline-flex items-center gap-1 rounded-md px-2 py-1 text-xs font-medium transition-all",
130	              copied
131	                ? "bg-green-50 text-green-600 border border-green-200"
132	                : "bg-white/80 text-slate-500 border border-slate-200 hover:bg-slate-50 hover:text-slate-700"
133	            )}
134	          >
135	            {copied ? (
136	              <>
137	                <Check className="h-3 w-3" />
138	                Copied
139	              </>
140	            ) : (
141	              <>
142	                <Copy className="h-3 w-3" />
143	                Copy
144	              </>
145	            )}
146	          </button>
147	        </TooltipTrigger>
148	        <TooltipContent side="top">
149	          <p>{copied ? "Copied to clipboard!" : "Copy AI suggestion"}</p>
150	        </TooltipContent>
151	      </Tooltip>
152	    </TooltipProvider>
153	  );
154	}
155	
156	// ── Enhanced Finding Wrapper ────────────────────────────────────
157	// Wraps each FindingCard with effort/impact badges + copy button on AI suggestion
158	
159	function EnhancedFinding({ finding }: { finding: Finding }) {
160	  return (
161	    <div className="relative">
162	      {/* Effort + Lift badges pinned to the top-right */}
163	      <div className="absolute -top-2.5 right-4 z-10 flex items-center gap-1.5">
164	        <span
165	          className={cn(
166	            "inline-flex items-center gap-1 rounded-full border px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide",
167	            getEffortColor(finding.effort)
168	          )}
169	        >
170	          <Zap className="h-2.5 w-2.5" />
171	          {getEffortLabel(finding.effort)}
172	        </span>
173	        {finding.estimated_lift && finding.estimated_lift !== "0%" && (
174	          <span className="inline-flex items-center gap-1 rounded-full border border-violet-200 bg-violet-50 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-violet-600">
175	            <TrendingUp className="h-2.5 w-2.5" />
176	            {finding.estimated_lift}
177	          </span>
178	        )}
179	      </div>
180	
181	      {/* The actual FindingCard */}
182	      <FindingCard finding={finding} />
183	
184	      {/* Copy button overlay on AI suggestion (only for non-premium, non-empty suggestions) */}
185	      {!finding.is_premium && finding.ai_suggestion && (
186	        <div className="absolute bottom-5 right-5">
187	          <CopyButton text={finding.ai_suggestion} />
188	        </div>
189	      )}
190	    </div>
191	  );
192	}
193	
194	// ── Stat Card ───────────────────────────────────────────────────
195	
196	function StatCard({
197	  label,
198	  value,
199	  icon: Icon,
200	  accent,
201	  subtitle,
202	}: {
203	  label: string;
204	  value: string | number;
205	  icon: React.ElementType;
206	  accent: string;
207	  subtitle?: string;
208	}) {
209	  return (
210	    <Card className="border-slate-200 shadow-none">
211	      <CardContent className="flex items-center gap-3.5 p-4">
212	        <div className={cn("flex h-10 w-10 shrink-0 items-center justify-center rounded-lg", accent)}>
213	          <Icon className="h-4.5 w-4.5" />
214	        </div>
215	        <div className="min-w-0">
216	          <p className="text-[22px] font-bold leading-tight text-foreground">{value}</p>
217	          <p className="text-xs text-muted-foreground">{label}</p>
218	          {subtitle && (
219	            <p className="mt-0.5 text-[10px] font-medium text-muted-foreground/70">{subtitle}</p>
220	          )}
221	        </div>
222	      </CardContent>
223	    </Card>
224	  );
225	}
226	
227	// ── Pillar Bar with Benchmark ───────────────────────────────────
228	
229	function PillarBarWithBenchmark({
230	  pillar,
231	  score,
232	  benchmark,
233	}: {
234	  pillar: string;
235	  score: number;
236	  benchmark: number;
237	}) {
238	  const config = CRO_PILLARS.find((p) => p.key === pillar);
239	  if (!config) return null;
240	
241	  const Icon = config.icon;
242	  const diff = score - benchmark;
243	  const diffLabel = diff >= 0 ? `+${diff}` : `${diff}`;
244	  const diffColor = diff >= 0 ? "text-green-600" : "text-red-500";
245	
246	  return (
247	    <div className="group">
248	      <div className="flex items-center gap-3">
249	        <Icon className="h-4 w-4 shrink-0 text-muted-foreground" />
250	        <span className="w-36 shrink-0 truncate text-sm text-slate-600">{config.label}</span>
251	        <div className="relative flex-1">
252	          {/* Track */}
253	          <div className="h-2.5 w-full overflow-hidden rounded-full bg-slate-100">
254	            <div
255	              className={cn("h-full rounded-full transition-all duration-1000 ease-out", getScoreBgColor(score))}
256	              style={{ width: `${score}%` }}
257	            />
258	          </div>
259	          {/* Benchmark marker */}
260	          <TooltipProvider delayDuration={100}>
261	            <Tooltip>
262	              <TooltipTrigger asChild>
263	                <div
264	                  className="absolute top-1/2 -translate-y-1/2 h-5 w-0.5 bg-slate-800/60 rounded-full"
265	                  style={{ left: `${benchmark}%` }}
266	                >
267	                  <div className="absolute -top-1 left-1/2 -translate-x-1/2 h-1.5 w-1.5 rounded-full bg-slate-700" />
268	                </div>
269	              </TooltipTrigger>
270	              <TooltipContent side="top" className="text-xs">
271	                <p>Industry avg: {benchmark}/100</p>
272	              </TooltipContent>
273	            </Tooltip>
274	          </TooltipProvider>
275	        </div>
276	        <span className={cn("w-10 text-right text-sm font-semibold", getScoreColor(score))}>
277	          {formatScore(score)}
278	        </span>
279	        <span className={cn("w-12 text-right text-xs font-medium", diffColor)}>
280	          {diffLabel} avg
281	        </span>
282	      </div>
283	    </div>
284	  );
285	}
286	
287	// ── Main Component ──────────────────────────────────────────────
288	
289	const AuditReport = () => {
290	  const { id } = useParams();
291	  const scan = MOCK_SCANS.find((s) => s.id === id) ?? MOCK_SCANS[0];
292	  const pillarResults = MOCK_PILLAR_RESULTS.filter((r) => r.scan_id === scan.id);
293	
294	  // Sort pillars by score ascending (worst first)
295	  const sortedPillars = [...pillarResults].sort((a, b) => a.score - b.score);
296	
297	  // Aggregate stats
298	  const allFindings = pillarResults.flatMap((p) => p.findings);
299	  const totalFindings = allFindings.length;
300	  const criticalCount = allFindings.filter((f) => f.severity === "critical").length;
301	  const quickWinCount = allFindings.filter((f) => f.effort === "quick" && f.severity !== "passed").length;
302	  const lockedFindings = allFindings.filter((f) => f.is_premium).length;
303	
304	  // Estimated total lift: parse "X-Y%" patterns and sum the midpoints
305	  const estimatedTotalLift = allFindings.reduce((sum, f) => {
306	    const match = f.estimated_lift.match(/(\d+(?:\.\d+)?)-?(\d+(?:\.\d+)?)?%/);
307	    if (match) {
308	      const low = parseFloat(match[1]);
309	      const high = match[2] ? parseFloat(match[2]) : low;
310	      return sum + (low + high) / 2;
311	    }
312	    return sum;
313	  }, 0);
314	
315	  // Key issues for overlay and sidebar
316	  const criticalFindings = allFindings
317	    .filter((f) => f.severity === "critical" || f.severity === "warning")
318	    .sort((a, b) => {
319	      const order: Record<Severity, number> = { critical: 0, warning: 1, info: 2, passed: 3 };
320	      return order[a.severity] - order[b.severity];
321	    })
322	    .slice(0, 5);
323	
324	  const score = scan.overall_score ?? 0;
325	  const percentile = getPercentileRank(score);
326	  const scoreLabel = getScoreLabel(score);
327	
328	  return (
329	    <PageTransition>
330	      <div className="space-y-8">
331	        {/* ── Breadcrumb ──────────────────────────────────────── */}
332	        <div className="flex items-center gap-2 text-sm text-muted-foreground">
333	          <Button variant="ghost" size="sm" asChild className="text-muted-foreground -ml-2 h-auto p-1">
334	            <Link to="/reports">
335	              <ArrowLeft className="mr-1 h-3.5 w-3.5" />
336	              Reports
337	            </Link>
338	          </Button>
339	          <span className="text-slate-300">/</span>
340	          <span className="truncate text-slate-500">
341	            {scan.page_title ?? scan.url}
342	          </span>
343	        </div>
344	
345	        {/* ── Report Header ───────────────────────────────────── */}
346	        <div className="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between">
347	          <div className="space-y-2">
348	            <h1 className="text-2xl font-bold text-foreground leading-tight sm:text-[28px]">
349	              {scan.page_title ?? "Audit Report"}
350	            </h1>
351	            <div className="flex items-center gap-2">
352	              <Globe className="h-3.5 w-3.5 text-muted-foreground" />
353	              <a
354	                href={scan.url}
355	                target="_blank"
356	                rel="noopener noreferrer"
357	                className="text-sm text-primary hover:underline truncate max-w-md"
358	              >
359	                {scan.url}
360	              </a>
361	            </div>
362	            <div className="flex flex-wrap items-center gap-2 text-sm text-muted-foreground">
363	              <div className="flex items-center gap-1">
364	                <Calendar className="h-3.5 w-3.5" />
365	                {scan.completed_at ? formatDateTime(scan.completed_at) : "In progress"}
366	              </div>
367	              <Separator orientation="vertical" className="h-3.5" />
368	              <Badge variant="outline" className="text-xs capitalize">
369	                {scan.page_type} page
370	              </Badge>
371	              <Badge variant="outline" className="text-xs">
372	                {deviceLabel(scan.device)}
373	              </Badge>
374	            </div>
375	          </div>
376	          <div className="flex items-center gap-2">
377	            <Button variant="outline" size="sm" className="border-slate-200">
378	              <Download className="mr-1.5 h-3.5 w-3.5" />
379	              PDF Report
380	            </Button>
381	            <Button variant="outline" size="sm" className="border-slate-200">
382	              <Share2 className="mr-1.5 h-3.5 w-3.5" />
383	              Share
384	            </Button>
385	            <Button size="sm">
386	              <RefreshCw className="mr-1.5 h-3.5 w-3.5" />
387	              Re-scan
388	            </Button>
389	          </div>
390	        </div>
391	
392	        {/* ── Summary Stats Row ───────────────────────────────── */}
393	        <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">
394	          <StatCard
395	            label="Total Findings"
396	            value={totalFindings}
397	            icon={BarChart2}
398	            accent="bg-slate-100 text-slate-600"
399	            subtitle={`Across ${pillarResults.length} pillars`}
400	          />
401	          <StatCard
402	            label="Critical Issues"
403	            value={criticalCount}
404	            icon={AlertCircle}
405	            accent="bg-red-100 text-red-600"
406	            subtitle="Fix these first"
407	          />
408	          <StatCard
409	            label="Quick Wins"
410	            value={quickWinCount}
411	            icon={Zap}
412	            accent="bg-green-100 text-green-600"
413	            subtitle="Low effort, high return"
414	          />
415	          <StatCard
416	            label="Est. Total Lift"
417	            value={`+${estimatedTotalLift.toFixed(1)}%`}
418	            icon={TrendingUp}
419	            accent="bg-violet-100 text-violet-600"
420	            subtitle="If all recommendations applied"
421	          />
422	        </div>
423	
424	        {/* ── Score Hero ──────────────────────────────────────── */}
425	        <Card
426	          className={cn(
427	            "border-slate-200 shadow-none overflow-hidden",
428	            getScoreBgLight(score)
429	          )}
430	        >
431	          <CardContent className="p-8">
432	            <div className="grid grid-cols-1 items-center gap-8 lg:grid-cols-3">
433	              {/* Giant score ring + percentile */}
434	              <div className="flex flex-col items-center gap-4 lg:items-center">
435	                <ScoreRing score={score} size={200} strokeWidth={12} />
436	                <div className="text-center">
437	                  <p className="text-sm font-medium text-foreground">
438	                    Your score of {score} is better than{" "}
439	                    <span className={cn("font-bold", getScoreColor(score))}>{percentile}%</span>
440	                    {" "}of landing pages we've analyzed
441	                  </p>
442	                  <p className="mt-1 text-xs text-muted-foreground">
443	                    Rating: <span className="font-semibold">{scoreLabel}</span> — based on {totalFindings} data points across 7 CRO pillars
444	                  </p>
445	                </div>
446	              </div>
447	
448	              {/* Pillar scores with benchmarks */}
449	              <div className="space-y-3.5 lg:col-span-2">
450	                <div className="mb-4 flex items-center justify-between">
451	                  <h3 className="text-sm font-semibold uppercase tracking-wider text-muted-foreground">
452	                    CRO Pillar Scores
453	                  </h3>
454	                  <div className="flex items-center gap-1.5 text-[10px] text-muted-foreground">
455	                    <div className="h-3 w-0.5 rounded-full bg-slate-800/60" />
456	                    <span>Industry benchmark</span>
457	                  </div>
458	                </div>
459	                {sortedPillars.map((result) => (
460	                  <PillarBarWithBenchmark
461	                    key={result.pillar}
462	                    pillar={result.pillar}
463	                    score={result.score}
464	                    benchmark={result.benchmark}
465	                  />
466	                ))}
467	                {/* Fallback bars for pillars without results */}
468	                {CRO_PILLARS.filter(
469	                  (p) => !pillarResults.some((r) => r.pillar === p.key)
470	                ).map((pillar) => (
471	                  <PillarBarWithBenchmark
472	                    key={pillar.key}
473	                    pillar={pillar.key}
474	                    score={0}
475	                    benchmark={getIndustryBenchmark(pillar.key)}
476	                  />
477	                ))}
478	              </div>
479	            </div>
480	          </CardContent>
481	        </Card>
482	
483	        {/* ── Annotated Mockup + Key Issues Sidebar ───────────── */}
484	        <div className="grid grid-cols-1 gap-6 lg:grid-cols-5">
485	          {/* Annotated Browser Mockup */}
486	          <div className="lg:col-span-3">
487	            <BrowserFrame url={scan.url}>
488	              <div className="relative h-[420px] overflow-hidden bg-gradient-to-br from-slate-50 via-white to-slate-50">
489	                {/* Simulated page structure */}
490	                <div className="absolute inset-0 p-4">
491	                  {/* Nav bar skeleton */}
492	                  <div className="flex items-center justify-between px-3 py-2">
493	                    <div className="h-5 w-24 rounded bg-slate-200/80" />
494	                    <div className="flex gap-3">
495	                      <div className="h-3 w-12 rounded bg-slate-200/60" />
496	                      <div className="h-3 w-12 rounded bg-slate-200/60" />
497	                      <div className="h-3 w-12 rounded bg-slate-200/60" />
498	                      <div className="h-6 w-16 rounded-md bg-slate-200/80" />
499	                    </div>
500	                  </div>
501	
502	                  {/* Hero section skeleton */}
503	                  <div className="mt-8 flex flex-col items-center px-6 text-center">
504	                    <div className="h-6 w-72 rounded bg-slate-200/80 mb-3" />
505	                    <div className="h-4 w-56 rounded bg-slate-200/50 mb-2" />
506	                    <div className="h-4 w-48 rounded bg-slate-200/40 mb-6" />
507	                    {/* Wireframe CTA area */}
508	                    <div className="h-3 w-36 rounded bg-slate-200/30" />
509	                  </div>
510	
511	                  {/* Features grid skeleton */}
