133	                  <div className="flex items-center gap-1.5">
134	                    <Sparkles className="h-3.5 w-3.5 text-primary" />
135	                    <p className="text-[11px] font-semibold uppercase tracking-widest text-primary">AI Suggestion</p>
136	                  </div>
137	                  <CopyInline text={finding.ai_suggestion} />
138	                </div>
139	                <p className="text-sm text-slate-700 leading-relaxed whitespace-pre-line">
140	                  {finding.ai_suggestion}
141	                </p>
142	              </div>
143	            )}
144	
145	            {/* Meta: category + effort on mobile */}
146	            <div className="flex items-center gap-3 text-[11px] text-muted-foreground">
